insert into companies (slug, name, sector, industry, company_type, location, size, rating, rating_bucket, about) values ('halcyon-group', 'Halcyon Group', 'RETAIL & APPAREL · DUBAI, UNITED ARAB EMIRATES', 'Retail & Apparel', 'Retail', 'Dubai, United Arab Emirates', '8,000 – 12,000', 4.61, '4.5 & up', 'Halcyon Group runs 340 stores and a fast-growing e-commerce arm across the Gulf. Design and product sit together under one VP, with a mandate to unify the checkout experience across brands by 2027.');
